(* [comment removed for export] *)
Lemma ConfigSvc_ro : forall LB m c S, ConfigSvc LB m c S ->
  ro_cells rsegs m c [C8 (wz VP_CONFIG_SVC)] /\ ro_cells rsegs m (c + O_CFG_HINT) [C4 (wz 4294967295)].
Proof.
  intros LB m c S (p & j4 & j7 & IN & CH & EV & _). split.
  - pose proof (rw_cells_ro_cell _ _ _ _ 0 _ CH eq_refl) as R. rewrite Z.add_0_r, EV in R. exact R.
  - pose proof (rw_cells_ro_cell _ _ _ _ 48 _ CH eq_refl) as R. exact R.
Qed.

