(* [comment removed for export] *)
(* [comment removed for export] *)

Definition CONFIG_GET_STACK : Z := 80 + GET_VALUE_STACK.

Definition cg_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (res errv' : word) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 res a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (bv_unsigned tp + -164, bv_unsigned tp + -164 + 4)]%Z m m'
    /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' (bv_unsigned tp + -164) [C4 errv']
    /\ CanaryReads m' /\ XStatics m'.

(* [comment removed for export] *)
Definition cg_stmt (pc : Z) (k : cfgkey) (dflt res : word) (errz : bool) : Prop :=
  forall (c lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (errv : word),
  F = bvmap_empty -> fc = Z_to_bv 32 0 ->
  ro_cells rsegs m c [C8 (wz VP_CONFIG_SVC)] ->
  ro_cells rsegs m (c + O_CFG_HINT) [C4 (wz 4294967295)] ->
  (c + SZ_CFG <= lo \/ bv_unsigned sp <= c) ->
  XStatics m ->
  rw_cells rsegs m (bv_unsigned tp + -164) [C4 errv] -> tp = Z_to_bv 64 RATP ->
  bv_unsigned sp mod 16 = 0 -> bv_unsigned sp <= 0x7fffffffffff ->
  stk rsegs m lo (bv_unsigned sp) -> lo + CONFIG_GET_STACK <= bv_unsigned sp -> hceil <= lo ->
  CanaryReads m ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (cg_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc res (if errz then wz 0 else errv) lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz c) (wz L_STR_SCHEDULER) (wz (key_lit k)) dflt (wz 0) a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m (seg_rom rsegs)).

(* [comment removed for export] *)
Definition cg_int_chint_stmt : Prop := forall dflt : word, cg_stmt P_CONFIG_GET_INT KChint dflt (wz 18446744073709551615) true.
Definition cg_int_default_stmt (k : cfgkey) : Prop :=
  forall d : Z, gv_null k = true -> 0 <= d < 2^31 -> cg_stmt P_CONFIG_GET_INT k (wz d) (wz d) false.
Definition cg_bool_locking_stmt : Prop := forall dflt : word, cg_stmt P_CONFIG_GET_BOOL KLocking dflt (wz 1) true.
Definition cg_bool_default_stmt (k : cfgkey) : Prop :=
  forall dflt : word, gv_null k = true -> cg_stmt P_CONFIG_GET_BOOL k dflt dflt false.
Definition cg_long_default_stmt (k : cfgkey) : Prop :=
  forall dflt : word, gv_null k = true -> cg_stmt P_CONFIG_GET_LONG k dflt dflt false.

(* [comment removed for export] *)
Lemma XS_config_vt' : forall m, XStatics m ->
  rw_cells rsegs m 0x7a3f0 [C8 (Z_to_bv 64 0x36588); C8 (Z_to_bv 64 0x2c154); C8 (Z_to_bv 64 0x2c15c); C8 (Z_to_bv 64 0x2c160); C8 (Z_to_bv 64 0x2c164)].
Proof. intros m XS. destruct XS as (_ & H0 & _). exact H0. Qed.

(* [comment removed for export] *)
Lemma XStatics_cg : forall lo sp tpv m m',
  XStatics m -> munch [(lo, sp); (tpv + -164, tpv + -164 + 4)]%Z m m' -> wmono rsegs m m' ->
  0xb4000 <= lo -> tpv = RATP -> XStatics m'.
Proof.
  intros lo sp tpv m m' XS MU WM LO ->. eapply XStatics_transport; [exact XS| exact MU| exact WM|].
  unfold RATP. constructor; [cbn; lia|]. constructor; [cbn; lia|]. constructor.
Qed.

Local Ltac cg_prologue pcname :=
  unfold cg_stmt;
  intros c lo ra sp gp tp t0 t1 t2 s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m errv;
  intros FZ FCZ VPTR HINT CSEP XS ERR TP SP16 SPHI ST LO HC CAN RA MI;
  pose proof LO as LO'; unfold CONFIG_GET_STACK, GET_VALUE_STACK, SNPRINTF_STACK in LO; unfold O_CFG_HINT, SZ_CFG in *;
  hcb; sp_range sp;
  let TPV := fresh "TPV" in
  assert (TPV : bv_unsigned tp = RATP) by (rewrite TP; apply unsigned_lit; unfold RATP; lia); unfold RATP in TPV;
  pose proof (XS_config_vt' _ XS) as VT;
  init_fp [(lo, bv_unsigned sp); (bv_unsigned tp + -164, bv_unsigned tp + -164 + 4)]%Z;
  unfold pcname, VP_CONFIG_SVC, wz in *;
  carve_frame 80%nat ST;
  (* [comment removed for export] *)
  do 5 step;
  (* [comment removed for export] *)
  do 5 step.

(* [comment removed for export] *)
Local Ltac cg_cut_frame FR sp :=
  lazymatch type of FR with context [CB 56 ?j] => remember j as J eqn:EJ; clear EJ end;
  apply (rw_cells_split_CB _ _ _ [] 56 _ _ [24; 8; 2; 22]%nat) in FR; [| reflexivity];
  cbn [mk_CB_cells app] in FR;
  apply (proj1 (rw_cells_app _ _ _ [CB 24 _; CB 8 _; CB 2 _] _)) in FR;
  let FR0 := fresh "FR0" in let FR1 := fresh "FR1" in let BUF := fresh "BUF" in let FR2 := fresh "FR2" in
  destruct FR as [FR0 FR1]; cbn [cells_size csize Nat.add] in FR1;
  replace (bv_unsigned sp + -80 + Z.of_nat 34) with (bv_unsigned sp + -46) in FR1 by lia;
  apply (proj1 (rw_cells_app _ _ _ [CB 22 _] _)) in FR1;
  destruct FR1 as [BUF FR2]; cbn [cells_size csize Nat.add] in FR2;
  replace (bv_unsigned sp + -46 + Z.of_nat 22) with (bv_unsigned sp + -24) in FR2 by lia.

(* [comment removed for export] *)
Local Ltac cg_side CAN MU :=
  first [ fast_assumption
        | reflexivity
        | (unfold wz, STRTOLL_STACK, GET_VALUE_STACK, SNPRINTF_STACK; rewrite ?unsigned_lit by lia;
           first [ fast_assumption | lia | Z.div_mod_to_equations; lia ])
        | (eapply CanaryReads_transport; [exact CAN | exact MU | |]; unfold G_GOT_STACK_CHK, G_STACK_CHK_GUARD; cbn; lia) ].

(* [comment removed for export] *)
Ltac if_tk := let K := fresh "K" in if_cases K;
  [ clear K | exfalso; zify_cond K; unfold wz in K; rewrite ?unsigned_lit in K by lia; first [lia | congruence] ].
Ltac if_nt := let K := fresh "K" in if_cases K;
  [ exfalso; zify_cond K; unfold wz in K; rewrite ?unsigned_lit in K by lia; first [lia | congruence] | clear K ].

(* [comment removed for export] *)
Local Ltac cg_call_gv k c lo sp CAN MU :=
  let GV := fresh "GV" in
  pose proof (get_value_spec k) as GV; unfold get_value_stmt in GV; cbn [key_lit gv_res gv_buf] in GV;
